<?php
declare(strict_types=1);
namespace CommunityHub;
final class People {
 public static function reviewLeave(int $id,int $actor,bool $approve,?string $notes):void{App::transaction(function()use($id,$actor,$approve,$notes){$l=App::row("SELECT l.*,u.member_status,COALESCE(sp.activity_status,'active') activity_status FROM loa_requests l JOIN users u ON u.id=l.user_id LEFT JOIN staff_profiles sp ON sp.user_id=u.id WHERE l.id=? FOR UPDATE",[$id]);if(!$l)throw new HttpError('Leave request not found.',404);if($l['status']!=='pending')throw new HttpError('Leave request has already been reviewed.',409);if($approve){App::query("UPDATE loa_requests SET status='approved',reviewed_by=?,reviewed_at=NOW(),review_notes=?,previous_member_status=?,previous_activity_status=?,activity_exempted=1 WHERE id=?",[$actor,$notes,$l['member_status'],$l['activity_status'],$id]);App::query("INSERT INTO staff_profiles(user_id,activity_status,updated_by) VALUES(?,'exempt',?) ON DUPLICATE KEY UPDATE activity_status='exempt',updated_by=VALUES(updated_by)",[$l['user_id'],$actor]);App::query("UPDATE users SET member_status='loa' WHERE id=?",[$l['user_id']]);App::query("INSERT INTO staff_activity_status_history(user_id,previous_status,new_status,reason,changed_by) VALUES(?,?,'exempt',?,?)",[$l['user_id'],$l['activity_status'],'Approved LOA #'.$id,$actor]);}else App::query("UPDATE loa_requests SET status='denied',reviewed_by=?,reviewed_at=NOW(),review_notes=? WHERE id=?",[$actor,$notes,$id]);App::query("INSERT INTO loa_status_history(loa_request_id,user_id,from_status,to_status,note,changed_by) VALUES(?,?,'pending',?,?,?)",[$id,$l['user_id'],$approve?'approved':'denied',$notes,$actor]);App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$l['user_id'],$approve?'Leave request approved':'Leave request reviewed',$approve?'Your leave request was approved. Activity requirements are paused.':'Your leave request was not approved. '.($notes??''),'/personnel/me/loa']);});}
 public static function restoreLeave(?int $actor=null):int{$rows=App::rows("SELECT id FROM loa_requests WHERE status='approved' AND activity_exempted=1 AND restored_at IS NULL AND end_date<CURDATE()");$count=0;foreach($rows as $r)$count+=App::transaction(function()use($r,$actor){$l=App::row("SELECT * FROM loa_requests WHERE id=? AND activity_exempted=1 AND restored_at IS NULL FOR UPDATE",[$r['id']]);if(!$l)return 0;App::row('SELECT id FROM users WHERE id=? FOR UPDATE',[$l['user_id']]);$other=App::row("SELECT id FROM loa_requests WHERE user_id=? AND id<>? AND status='approved' AND activity_exempted=1 AND end_date>=CURDATE() LIMIT 1",[$l['user_id'],$l['id']]);if($other)return 0;$status=in_array($l['previous_member_status'],['applicant','recruit','active','inactive','removed'],true)?$l['previous_member_status']:'active';$activity=in_array($l['previous_activity_status'],['active','watch','inactive'],true)?$l['previous_activity_status']:'active';App::query('UPDATE users SET member_status=? WHERE id=?',[$status,$l['user_id']]);App::query('INSERT INTO staff_profiles(user_id,activity_status,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE activity_status=VALUES(activity_status),updated_by=VALUES(updated_by)',[$l['user_id'],$activity,$actor]);App::query('UPDATE loa_requests SET activity_exempted=0,restored_at=NOW() WHERE id=?',[$l['id']]);App::query("INSERT INTO staff_activity_status_history(user_id,previous_status,new_status,reason,changed_by) VALUES(?,'exempt',?,?,?)",[$l['user_id'],$activity,'LOA #'.$l['id'].' ended; activity tracking restored.',$actor]);App::query("INSERT INTO loa_status_history(loa_request_id,user_id,from_status,to_status,note,changed_by) VALUES(?,?,'approved','completed','Leave period ended and activity tracking was restored.',?)",[$l['id'],$l['user_id'],$actor]);App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$l['user_id'],'Leave period ended','Your approved leave has ended and normal activity tracking has resumed.','/personnel/me/loa']);return 1;});return $count;}
 public static function activity(int $days=7,bool $snapshot=false,?int $evaluate=null):array{$start=date('Y-m-d',strtotime('-'.$days.' days'));$end=date('Y-m-d');$rows=App::rows("SELECT u.id,u.display_name,u.discord_username,u.callsign,u.rank_name,d.name department_name,COALESCE(sp.activity_status,'active') activity_status,sp.activity_requirement_minutes,FLOOR(COALESCE(SUM(TIMESTAMPDIFF(SECOND,p.clocked_in_at,COALESCE(p.clocked_out_at,NOW()))),0)/60) patrol_minutes,COUNT(p.id) patrol_sessions,MAX(p.clocked_in_at) last_patrol FROM users u LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN staff_profiles sp ON sp.user_id=u.id LEFT JOIN patrol_sessions p ON p.user_id=u.id AND p.clocked_in_at>=? WHERE u.member_status IN('recruit','active') GROUP BY u.id,u.display_name,u.discord_username,u.callsign,u.rank_name,d.name,sp.activity_status,sp.activity_requirement_minutes ORDER BY patrol_minutes DESC,u.display_name",[$start]);foreach($rows as $r){$need=$r['activity_requirement_minutes']!==null?(int)$r['activity_requirement_minutes']:null;if($snapshot||$evaluate!==null)App::query('INSERT INTO staff_activity_snapshots(user_id,period_start,period_end,patrol_minutes,patrol_sessions,requirement_minutes,requirement_met) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE patrol_minutes=VALUES(patrol_minutes),patrol_sessions=VALUES(patrol_sessions),requirement_minutes=VALUES(requirement_minutes),requirement_met=VALUES(requirement_met),generated_at=CURRENT_TIMESTAMP',[$r['id'],$start,$end,$r['patrol_minutes'],$r['patrol_sessions'],$need,(int)($need===null||$r['patrol_minutes']>=$need)]);if($evaluate!==null&&$need!==null&&$r['activity_status']!=='exempt'){$ratio=$need>0?(int)$r['patrol_minutes']/$need:1;$desired=$ratio>=1?'active':($ratio>=0.5?'watch':'inactive');if($desired!==$r['activity_status']){self::activityStatus((int)$r['id'],$desired,'Automatic '.$days.'-day activity evaluation: '.$r['patrol_minutes'].'/'.$need.' required minutes.',$evaluate);App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$r['id'],'Activity status updated','Your activity status changed to '.$desired.'.','/personnel/'.$r['id']]);}}}return ['rows'=>$rows,'period_start'=>$start,'period_end'=>$end];}
 public static function activityStatus(int $id,string $status,string $reason,int $actor):void{if(!in_array($status,['active','watch','inactive','exempt'],true))throw new HttpError('Select a valid activity status.');$old=App::row('SELECT activity_status FROM staff_profiles WHERE user_id=?',[$id]);App::query('INSERT INTO staff_profiles(user_id,activity_status,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE activity_status=VALUES(activity_status),updated_by=VALUES(updated_by)',[$id,$status,$actor]);App::query('INSERT INTO staff_activity_status_history(user_id,previous_status,new_status,reason,changed_by) VALUES(?,?,?,?,?)',[$id,$old['activity_status']??null,$status,$reason?:null,$actor]);}
 public static function readiness(bool $sync=true):array{$rows=App::rows("SELECT d.id,d.name,d.slug,COALESCE(rs.minimum_on_duty,0) minimum_on_duty,COALESCE(rs.minimum_supervisors,0) minimum_supervisors,COALESCE(rs.warning_when_below,1) warning_when_below,COALESCE(rs.critical_when_empty,1) critical_when_empty,COUNT(DISTINCT CASE WHEN au.last_seen_at>=DATE_SUB(NOW(),INTERVAL 90 SECOND) THEN au.id END) on_duty,COUNT(DISTINCT CASE WHEN au.last_seen_at>=DATE_SUB(NOW(),INTERVAL 90 SECOND) AND (LOWER(COALESCE(au.rank_name,'')) LIKE '%supervisor%' OR LOWER(COALESCE(au.rank_name,'')) LIKE '%sergeant%' OR LOWER(COALESCE(au.rank_name,'')) LIKE '%lieutenant%' OR LOWER(COALESCE(au.rank_name,'')) LIKE '%captain%' OR LOWER(COALESCE(au.rank_name,'')) LIKE '%chief%' OR LOWER(COALESCE(au.rank_name,'')) LIKE '%command%') THEN au.id END) supervisors FROM departments d LEFT JOIN department_readiness_settings rs ON rs.department_id=d.id LEFT JOIN fivem_active_units au ON LOWER(au.department)=LOWER(d.name) WHERE d.is_active=1 GROUP BY d.id,d.name,d.slug,rs.minimum_on_duty,rs.minimum_supervisors,rs.warning_when_below,rs.critical_when_empty ORDER BY d.name");foreach($rows as &$r){$r['state']=$r['critical_when_empty']&&$r['minimum_on_duty']>0&&$r['on_duty']==0?'critical':(($r['warning_when_below']&&$r['on_duty']<$r['minimum_on_duty'])||$r['supervisors']<$r['minimum_supervisors']?'warning':'ready');if(!$sync)continue;$fingerprint='readiness:'.$r['id'];if($r['state']==='ready'){App::query('UPDATE command_alerts SET is_resolved=1,resolved_at=NOW() WHERE fingerprint=? AND is_resolved=0',[$fingerprint]);continue;}$title=$r['name'].($r['state']==='critical'?' has no units on duty':' is below staffing target');$message=$r['on_duty'].'/'.$r['minimum_on_duty'].' units on duty and '.$r['supervisors'].'/'.$r['minimum_supervisors'].' supervisors available.';App::query("INSERT INTO command_alerts(alert_type,severity,department_id,title,message,fingerprint,is_resolved,resolved_at) VALUES('department_readiness',?,?,?,?,?,0,NULL) ON DUPLICATE KEY UPDATE severity=VALUES(severity),title=VALUES(title),message=VALUES(message),is_resolved=0,resolved_at=NULL,updated_at=CURRENT_TIMESTAMP",[$r['state'],$r['id'],$title,$message,$fingerprint]);}return $rows;}
 public static function syncDiscord(int $id):void{$u=App::row('SELECT * FROM users WHERE id=?',[$id]);if(empty($u['discord_id']))return;try{$d=$u['department_id']?App::row('SELECT * FROM departments WHERE id=?',[$u['department_id']]):null;$rank=$d?App::row('SELECT * FROM department_ranks WHERE department_id=? AND name=?',[$d['id'],$u['rank_name']]):null;$desired=[];if(!empty($d['discord_role_id']))$desired[]=$d['discord_role_id'];if($u['role']==='recruit'&&!empty($d['recruit_discord_role_id']))$desired[]=$d['recruit_discord_role_id'];if(in_array($u['role'],['member','reviewer',...Domain::STAFF],true)&&!empty($d['member_discord_role_id']))$desired[]=$d['member_discord_role_id'];if(!empty($rank['discord_role_id']))$desired[]=$rank['discord_role_id'];$mapped=[];foreach(App::rows('SELECT discord_role_id,recruit_discord_role_id,member_discord_role_id FROM departments') as $row)foreach($row as $v)if($v)$mapped[]=$v;foreach(App::rows('SELECT discord_role_id FROM department_ranks WHERE discord_role_id IS NOT NULL') as $row)$mapped[]=$row['discord_role_id'];$member=App::discord('GET','guilds/'.App::env('DISCORD_GUILD_ID').'/members/'.$u['discord_id']);$current=$member['roles']??[];foreach(array_unique($desired) as $role)if(!in_array($role,$current,true))App::discord('PUT','guilds/'.App::env('DISCORD_GUILD_ID').'/members/'.$u['discord_id'].'/roles/'.$role);foreach(array_unique($mapped) as $role)if(in_array($role,$current,true)&&!in_array($role,$desired,true))App::discord('DELETE','guilds/'.App::env('DISCORD_GUILD_ID').'/members/'.$u['discord_id'].'/roles/'.$role);}catch(\Throwable $e){error_log('[CommunityHub PHP] Discord role synchronization unavailable.');}}
}
